<script setup>
import { onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Eye, RefreshCw } from '@lucide/vue'
import PlatformPeriodFilter from '../../components/platform/PlatformPeriodFilter.vue'
import { getPlatformSite } from '../../api/platform'
const route = useRoute(), period = ref({ period: '30d' }), site = ref(null), loading = ref(true), error = ref('')
async function load() { loading.value = true; try { site.value = (await getPlatformSite(route.params.siteId, period.value)).data; error.value = '' } catch (e) { error.value = e.response?.data?.detail || 'Сайт не найден.' } finally { loading.value = false } }
watch(() => route.params.siteId, load); onMounted(load)
</script>
<template><section class="space-y-4"><div class="rounded-3xl border-2 border-violet-300 bg-violet-50 p-4"><p class="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-violet-700"><Eye :size="16" /> Просмотр от имени владельца сайта · только чтение</p><h2 class="mt-2 text-xl font-bold text-slate-900">{{ site?.name || 'Сайт' }}</h2><p class="text-sm text-slate-600">Сейчас открыты данные сайта {{ site?.domain || '' }}. Авторизация пользователя не изменялась.</p></div><div class="flex justify-end rounded-3xl bg-slate-900 p-4"><PlatformPeriodFilter v-model="period" @change="load" /></div><div v-if="error" class="rounded-2xl bg-red-50 p-4 text-red-800">{{ error }}</div><div v-if="loading" class="rounded-3xl bg-white p-12 text-center"><RefreshCw class="inline animate-spin" /></div><template v-else-if="site"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><article v-for="item in [['Посещения',site.visits],['Посетители',site.unique_visitors],['Просмотры',site.page_views],['Заявки',site.leads],['Конверсия',`${site.conversion}%`],['Ошибки',site.errors],['Тариф',site.plan || 'Не выбран'],['Подписка',site.subscription_status]]" :key="item[0]" class="rounded-2xl bg-white p-4 shadow-soft"><p class="text-xs text-slate-500">{{ item[0] }}</p><strong class="mt-2 block text-xl">{{ item[1] }}</strong></article></div><div class="grid gap-4 lg:grid-cols-2"><article class="rounded-3xl bg-white p-5 shadow-soft"><h3 class="font-semibold">Основное</h3><dl class="mt-4 grid grid-cols-2 gap-3 text-sm"><dt class="text-slate-500">Владелец</dt><dd>{{ site.owner }} · {{ site.owner_email }}</dd><dt class="text-slate-500">Статус</dt><dd>{{ site.is_active ? 'Активен' : 'Отключён' }}</dd><dt class="text-slate-500">Подключён</dt><dd>{{ new Date(site.created_at).toLocaleString('ru-RU') }}</dd><dt class="text-slate-500">Ключ трекера</dt><dd>{{ site.tracker_key || 'Нет отдельного разрешения' }}</dd></dl></article><article class="rounded-3xl bg-white p-5 shadow-soft"><h3 class="font-semibold">Последние заявки</h3><div v-for="lead in site.latest_leads" :key="lead.id" class="mt-3 flex justify-between text-sm"><span>{{ lead.name }} · {{ lead.status }}</span><span class="text-slate-500">{{ new Date(lead.created_at).toLocaleDateString('ru-RU') }}</span></div><p v-if="!site.latest_leads.length" class="mt-4 text-sm text-slate-500">Заявок пока нет.</p></article><article class="rounded-3xl bg-white p-5 shadow-soft"><h3 class="font-semibold">История проверок сайта</h3><div v-for="item in site.seo_audits" :key="item.id" class="mt-3 flex justify-between text-sm"><span>{{ item.status }}</span><b>{{ item.seo_score }}</b></div></article><article class="rounded-3xl bg-white p-5 shadow-soft"><h3 class="font-semibold">История AI-рекомендаций</h3><RouterLink v-for="item in site.recommendations" :key="item.id" :to="`/platform/recommendations/${item.id}`" class="mt-3 flex justify-between text-sm text-violet-700"><span>{{ item.recommendation_type }}</span><span>{{ item.status }}</span></RouterLink></article></div></template></section></template>
